const PAGE = '<!doctype html><title>t</title><main><button id="go">reveal the number</button><p id="out">not clicked</p><div id="hidden" style="display:none">42</div>' + '<scr'+'ipt>document.getElementById("go").addEventListener("click",function(){document.getElementById("out").textContent="clicked";document.getElementById("hidden").style.display="block";});</scr'+'ipt></main>';
const URL = 'data:text/html;charset=utf-8,' + encodeURIComponent(PAGE);
const tab = await openTab(URL);
await sleep(250);
await tab.locator('#go').click();
const out = await tab.evaluate(() => document.querySelector('#out').textContent);
await tab.close();
console.log('EVAL_JSON ' + JSON.stringify({ clicked: out === 'clicked' }));

const src = await fs.readFile('../../codemode/cm.js', 'utf8');
(0, eval)(src);
const PAGE = '<!doctype html><title>t</title><main><button id="go">reveal the number</button><p id="out">not clicked</p><div id="hidden" style="display:none">42</div>' + '<scr'+'ipt>document.getElementById("go").addEventListener("click",function(){document.getElementById("out").textContent="clicked";document.getElementById("hidden").style.display="block";});</scr'+'ipt></main>';
const URL = 'data:text/html;charset=utf-8,' + encodeURIComponent(PAGE);
const res = await cm.run({
  items: [{ url: URL }], limit: 1, maxTabs: 2, deadlineMs: 30000,
  onItem: async (tab) => {
    await sleep(250);
    await tab.locator('#go').click();
    return tab.evaluate(() => document.querySelector('#out').textContent);
  },
});
console.log('EVAL_JSON ' + JSON.stringify({ clicked: res.items[0].value === 'clicked', status: res.status }));
